-- Plain DDL mirror of db/migrations/00001_init.sql for sqlc generation.
CREATE TABLE tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE users (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE inquiries (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'seed', subject TEXT NOT NULL, redacted_body TEXT NOT NULL, normalized_body_hash TEXT NOT NULL, order_no_hint TEXT, status TEXT NOT NULL DEFAULT 'new', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE customers (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, synthetic_name TEXT NOT NULL, synthetic_contact_ref TEXT NOT NULL);
CREATE TABLE orders (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, customer_id TEXT NOT NULL, order_no TEXT NOT NULL, item TEXT NOT NULL, ordered_at TEXT NOT NULL, delivery_status TEXT NOT NULL, UNIQUE(tenant_id, order_no));
CREATE TABLE kb_articles (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, title TEXT NOT NULL, intent_tags JSONB NOT NULL DEFAULT '[]', body TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, effective_from TIMESTAMPTZ, effective_to TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'active', updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE kb_chunks (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, article_id TEXT NOT NULL REFERENCES kb_articles(id), chunk_index INTEGER NOT NULL, text TEXT NOT NULL, tokenized_text TEXT NOT NULL, embedding TEXT, embedding_model TEXT, index_version TEXT NOT NULL DEFAULT 'lexical-v1');
CREATE TABLE runs (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, inquiry_id TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'queued', model_route TEXT, prompt_version TEXT, config_snapshot JSONB, usage_json JSONB, cost_jpy NUMERIC, trace_id TEXT, lease_owner TEXT, lease_expires_at TIMESTAMPTZ, heartbeat_at TIMESTAMPTZ, attempt_count INTEGER NOT NULL DEFAULT 0, last_error_code TEXT, idempotency_key TEXT UNIQUE, escalation_reason TEXT, handoff_summary TEXT, started_at TIMESTAMPTZ, finished_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE run_steps (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, run_id TEXT NOT NULL REFERENCES runs(id), step_key TEXT NOT NULL, attempt INTEGER NOT NULL, state TEXT NOT NULL, input_redacted JSONB, output_redacted JSONB, prompt_version TEXT, model TEXT, started_at TIMESTAMPTZ, finished_at TIMESTAMPTZ, duration_ms INTEGER, trace_id TEXT, span_id TEXT, error_code TEXT, UNIQUE(run_id, step_key, attempt));
CREATE TABLE tool_calls (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, run_id TEXT, server TEXT NOT NULL, tool TEXT NOT NULL, risk_level TEXT NOT NULL, args_redacted JSONB, status TEXT NOT NULL, latency_ms INTEGER, trace_id TEXT, span_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE drafts (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, run_id TEXT NOT NULL REFERENCES runs(id), revision INTEGER NOT NULL, body TEXT NOT NULL, cited_article_ids JSONB NOT NULL, factual_references JSONB NOT NULL, verification_json JSONB, content_hash TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending_review', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(run_id, revision));
CREATE TABLE proposed_actions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, draft_id TEXT NOT NULL REFERENCES drafts(id), run_id TEXT, action_type TEXT NOT NULL, canonical_payload JSONB NOT NULL, payload_hash TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'proposed', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE approvals (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, draft_id TEXT NOT NULL REFERENCES drafts(id), draft_revision INTEGER NOT NULL, draft_hash TEXT NOT NULL, operator_id TEXT NOT NULL, selected_action_ids JSONB NOT NULL, policy_version TEXT NOT NULL, approved_at TIMESTAMPTZ NOT NULL DEFAULT now(), rejected_reason TEXT);
CREATE TABLE execution_jobs (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, proposed_action_id TEXT NOT NULL UNIQUE REFERENCES proposed_actions(id), idempotency_key TEXT NOT NULL UNIQUE, state TEXT NOT NULL DEFAULT 'queued', lease_owner TEXT, lease_expires_at TIMESTAMPTZ, heartbeat_at TIMESTAMPTZ, attempts INTEGER NOT NULL DEFAULT 0, result_json JSONB, failure_code TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE tickets (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, inquiry_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', priority TEXT NOT NULL DEFAULT 'normal', source_action_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ticket_notes (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, ticket_id TEXT NOT NULL REFERENCES tickets(id), body TEXT NOT NULL, source_action_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE outbox_messages (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, inquiry_id TEXT NOT NULL, draft_revision INTEGER NOT NULL, body TEXT NOT NULL, delivery_state TEXT NOT NULL DEFAULT 'sent_demo', source_action_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_events (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, actor_type TEXT NOT NULL, actor_id TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, before_hash TEXT, after_hash TEXT, trace_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE eval_runs (id TEXT PRIMARY KEY, dataset_version TEXT, prompt_version TEXT, model TEXT, index_version TEXT, report_json JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
